const body = $input.first().json.body || $input.first().json;

// Handle Slack URL verification challenge
if (body.type === 'url_verification') {
  return [{ json: { challenge: body.challenge, _isChallenge: true } }];
}

// Extract event data
const event = body.event || {};
const text = event.text || '';
const channel = event.channel || '';
const user = event.user || '';
const bot_id = event.bot_id; // undefined for real users

// Ignore bot messages
if (bot_id) {
  return [{ json: { _skip: true } }];
}

// Route to agent based on keywords / channel
let agentId = 'main';
const textLower = text.toLowerCase();

if (textLower.includes('code') || textLower.includes('bug') || textLower.includes('deploy') || textLower.includes('pr')) {
  agentId = 'eng';
} else if (textLower.includes('security') || textLower.includes('vuln') || textLower.includes('breach')) {
  agentId = 'infosec';
} else if (textLower.includes('cost') || textLower.includes('budget') || textLower.includes('spend') || textLower.includes('portfolio')) {
  agentId = 'finance';
} else if (textLower.includes('research') || textLower.includes('market') || textLower.includes('analysis')) {
  agentId = 'research';
} else if (textLower.includes('ticket') || textLower.includes('ops') || textLower.includes('deploy') || textLower.includes('status')) {
  agentId = 'ops';
}

const message = `SLACK MESSAGE from ${user} in ${channel}:\n${text}\n\nRespond appropriately.`;
return [{ json: { agentId, message, channel, user, _skip: false, _isChallenge: false } }];
